309  handle_compressed (ctrl_t ctrl, void *procctx, PKT_compressed *cd,
   310                     int (*callback)(IOBUF, void *), void *passthru )
   311  {
   312      int rc;
   313
   314      if(check_compress_algo(cd->algorithm))
   315        return GPG_ERR_COMPR_ALGO;
   316      if(cd->algorithm) {
   317          compress_filter_context_t *cfx;
   318
   319          cfx = xmalloc_clear (sizeof *cfx);
   320          cfx->release = release_context;
   321          cfx->algo = cd->algorithm;
   322          if (push_compress_filter(cd->buf, cfx, cd->algorithm))
   323            xfree (cfx);
   324      }
   325      if( callback )
   326          rc = callback(cd->buf, passthru );
   327      else
   328        rc = proc_packets (ctrl,procctx, cd->buf);
   329      cd->buf = NULL;
   330      return rc;
   331  }
