   340  /* Push a compress filter and return 0 if that succeeded.  */
   341  gpg_error_t
   342  push_compress_filter2(IOBUF out,compress_filter_context_t *zfx,
   343                        int algo,int rel)
   344  {
   345    gpg_error_t err = gpg_error (GPG_ERR_FALSE);
   346
   347    if(algo>=0)
   348      zfx->algo=algo;
   349    else
   350      zfx->algo=DEFAULT_COMPRESS_ALGO;
   351
   352    switch(zfx->algo)
   353      {
   354      case COMPRESS_ALGO_NONE:
   355        break;
   356
   357  #ifdef HAVE_ZIP
   358      case COMPRESS_ALGO_ZIP:
   359      case COMPRESS_ALGO_ZLIB:
   360        iobuf_push_filter2(out,compress_filter,zfx,rel);
   361        err = 0;
   362        break;
   363  #endif
   364
   365  #ifdef HAVE_BZIP2
   366      case COMPRESS_ALGO_BZIP2:
   367        iobuf_push_filter2(out,compress_filter_bz2,zfx,rel);
   368        err = 0;
   369        break;
   370  #endif
   371
   372      default:
   373        BUG();
   374      }
   375
   376    return err;
   377  }
